head.script:
scwin.screenId = "jldfil16400n";

///////// 1. 변수 및 선언 영역 /////////



///////// 2. 초기화 영역 /////////

// 현재 시각 파생값 충전 — as-is JSP 계산분(서버 데이터 아님). 진입점 선두 단계.
/**
 * @method
 * @name scwin.init_nowVars
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_nowVars = function () {
    const pc = $c.util.getComponent('dma_pageContext');
    if (!pc || !pc.set || !pc.get) { return; }
    if (!pc.get("today")) { pc.set("today", $c.date.getServerDateTime("yyyyMMdd")); }
};

// 조건 평가 — 진입점에서 1회. 데이터 재적재 시 ev:ondataload 가 다시 부른다.
/**
 * @method
 * @name scwin.init_conds
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_conds = async function () {
    const binds = [{ id: "if_disclsEduApctTpCd", fn: function(){ return ((((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : (console.warn("[sdd] 컨텍스트 키 미충전 — " + "corpUserTpCd" + " (as-is EL 부재 = 빈값이라 진행합니다)"), ""))(dma_pageContext.get("corpUserTpCd")) === '61' && (dlt_educationList.getCellData(0, "disclsEduApctTpCd") ?? (() => { throw new Error("unresolved:" + "education.disclsEduApctTpCd"); })()) === '81') ||
                    (((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : (console.warn("[sdd] 컨텍스트 키 미충전 — " + "corpUserTpCd" + " (as-is EL 부재 = 빈값이라 진행합니다)"), ""))(dma_pageContext.get("corpUserTpCd")) === '62' && (dlt_educationList.getCellData(0, "disclsEduApctTpCd") ?? (() => { throw new Error("unresolved:" + "education.disclsEduApctTpCd"); })()) === '82') || 
                    (((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : (console.warn("[sdd] 컨텍스트 키 미충전 — " + "corpUserTpCd" + " (as-is EL 부재 = 빈값이라 진행합니다)"), ""))(dma_pageContext.get("corpUserTpCd")) === '63' && (dlt_educationList.getCellData(0, "disclsEduApctTpCd") ?? (() => { throw new Error("unresolved:" + "education.disclsEduApctTpCd"); })()) === '82')); } }];
    let applied = 0;
    for (let i = 0; i < binds.length; i++) {
        const b = binds[i];
        try {
            const ok = !!b.fn();
            const comp = $c.util.getComponent(b.id);
            if (comp && comp.setStyle) { comp.setStyle("display", ok ? "" : "none"); }
            else if (comp) { if (ok) { if (comp.show) { comp.show(); } } else if (comp.hide) { comp.hide(); } }
            if (ok && b.grids) {
                for (let gi = 0; gi < b.grids.length; gi++) {
                    const gc = $c.util.getComponent(b.grids[gi]);
                    if (gc && gc.refreshGridView) { gc.refreshGridView(); }
                }
            }
            applied++;
        } catch (e) { await $c.exception.handleError(e, { notify: "none", context: "conds:" + b.id }); }
    }
    return applied;
};

// 제너레이터 채움 — 진입점(onpageload)에서 순차 실행.
/**
 * @method
 * @name scwin.init_fillGen
 * @author Inswave
 * @date 2026. 09. 29
 * @param boxId
 * @returns
 * @hidden N
*/
scwin.init_fillGen = function (boxId) {
    // 채우지 못한 자리를 모은다(동작은 계속 — 화면은 종전과 같다).
    const genSkip = [];
    let genCleared = 0;
    const genFills = [{ genId: "c_foreach_33", entity: "dlt_educationList", countIds: [], cells: [{ childId: "option_35", fn: function (v, i) { return String(v("disclsEduApplSeq")) + "," + String(v("disclsEduAcptStrtDd")) + "," + String(v("disclsEduAcptEndDd")) + "," + String(v("disclsEduEvtItmExpYn")); } }, { childId: "__rc0", fn: function (v, i) { return String(v("disclsEduCrsNm")); } }] }];
    const gf = genFills;
    for (let g = 0; g < gf.length; g++) {
        const f = gf[g];
        if (boxId && f.entity !== boxId) { continue; }
        const gen = $c.util.getComponent(f.genId);
        const ds = $c.util.getComponent(f.entity);
        if (!gen || !ds || !ds.getTotalRow) { genSkip.push({ gen: f.genId, box: f.entity, why: !gen ? 'no-generator' : 'no-box' }); continue; }
        const n = ds.getTotalRow();
        if (!n) { genSkip.push({ gen: f.genId, box: f.entity, why: 'empty-box' }); continue; }
        // 멱등 — 이미 채워진 제너레이터는 건너뛴다(플래그 없이 컴포넌트 상태로 판단).
        //   단, 상자를 지정해 «다시 그리라» 고 부른 경우(데이터가 새로 담긴 때)는 비우고 다시 채운다.
        if (gen.getLength && gen.getLength() > 0) {
            if (!boxId) { continue; }
            const had = gen.getLength();
            while (gen.getLength() > 0) { gen.removeChild(); }
            genCleared += had;
        }
        let row = 0;
        const cell = function (col) { const v = ds.getCellData(row, col); return (v === undefined || v === null) ? '' : v; };
        for (let i = 0; i < n; i++) {
            row = i;
            gen.insertChild(i);
            for (let c = 0; c < f.cells.length; c++) {
                const ch = gen.getChild(i, f.cells[c].childId);
                if (!ch || !ch.setValue) { continue; }
                ch.setValue(f.cells[c].fn(cell, i));
            }
            for (let k = 0; k < f.countIds.length; k++) {
                const cn = gen.getChild(i, f.countIds[k]);
                if (cn && cn.setValue) { cn.setValue(String(i + 1)); }
            }
            // 행 조건 — 마지막 행에만 보이는 자리.
            if (f.rowConds) {
                for (let rc = 0; rc < f.rowConds.length; rc++) {
                    const rn = gen.getChild(i, f.rowConds[rc].childId);
                    if (!rn) { continue; }
                    const show = (f.rowConds[rc].kind === 'last') ? (i === n - 1) : true;
                    if (rn.setStyle) { rn.setStyle('display', show ? '' : 'none'); }
                }
            }
        }
    }
    if (genSkip.length) {
        // 우리 계측이 읽는 자리 — 화면 동작에는 영향이 없다.
        scwin.genFillSkipped = genSkip;
    }
    if (genCleared) { scwin.genFillCleared = (scwin.genFillCleared || 0) + genCleared; }
};

// [A] 초기 목록 미해결 — jldfil16400n: 열자마자 목록을 채울 근거가 없다(진입 URL 0 · 자기 목록 tx 0 · 화면 자신의 액션 URL 도 못 가름)


// 화면 전환 파라미터 수신 — 엔진 표준(§106). 진입 파라미터 전체를 컨텍스트 dataMap 에 담는다. onpageload 합성 단계.
/**
 * @method
 * @name scwin.init_recvParam
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

// 화면 진입점 — 초기화 단계를 데이터 의존 순서로 호출한다.
/**
 * @method
 * @name scwin.onpageload
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        scwin.init_nowVars();
        scwin.init_fillGen();
        await scwin.init_conds();
    } catch (e) {
        $c.exception.handleError(e, { context: 'jldfil16400n.onpageload' });
    }
};


///////// 3. 컴포넌트 이벤트 영역 /////////

/**
 * @event
 * @name scwin.slc_sltEduRnd1_onchange
 * @author Inswave
 * @date 2026. 09. 29
 * @param e
 * @returns
 * @hidden N
*/
scwin.slc_sltEduRnd1_onchange = function(e){
    try {
        const ev = e;
        const event = ev;
        const selfVar = (ev && (ev.element || ev.target || ev.srcElement)) || this;
        /* sdd-asis-lifecycle:begin slc_sltEduRnd1_onchange — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
        scwin.getDsclEduRct(selfVar)
        /* sdd-asis-lifecycle:end */

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldfil16400n.slc_sltEduRnd1_onchange' }); }
};

/**
 * @event
 * @name scwin.btn_Submit_onclick
 * @author Inswave
 * @date 2026. 09. 29
 * @param e
 * @returns
 * @hidden N
*/
scwin.btn_Submit_onclick = async function(e){
    try {
        const ev = e;
        const event = ev;
        const selfVar = (ev && (ev.element || ev.target || ev.srcElement)) || this;
        /* sdd-asis-lifecycle:begin btn_Submit_onclick — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
        await scwin.submit()
        /* sdd-asis-lifecycle:end */

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldfil16400n.btn_Submit_onclick' }); }
};

/**
 * @event
 * @name scwin.btn_Reset_onclick
 * @author Inswave
 * @date 2026. 09. 29
 * @param e
 * @returns
 * @hidden N
*/
scwin.btn_Reset_onclick = function(e){
    try {
        const ev = e;
        const event = ev;
        const selfVar = (ev && (ev.element || ev.target || ev.srcElement)) || this;
        /* sdd-asis-lifecycle:begin btn_Reset_onclick — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
        scwin.reset()
        /* sdd-asis-lifecycle:end */

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldfil16400n.btn_Reset_onclick' }); }
};


///////// 4. 서브미션 콜백 영역 /////////

/**
 * @method
 * @name scwin.tx_fn_Submit
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.tx_fn_Submit = async function () {
    const sbmOptions = {
        id: "tx_fn_Submit",
        method: "post",
        action: "/support/eduRspn.do",
        ref: "dma_SubmitReq",
        target: "dlt_educationList=body.content",
        isProcessMsg: false
    };
    let res = null;
    try { res = await $c.sbm.executeDynamic(sbmOptions); }
    catch (_e) { await $c.exception.handleError(_e, { context: "jldfil16400n.tx_fn_Submit" }); return null; }
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
        return res;
    }

    return res;
};


///////// 5. 일반/업무 함수 영역 /////////

/**
 * @method
 * @name scwin.submit
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.submit = async function () {
    /* sdd-asis-lifecycle:begin fn_Submit — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const form = (document.eduForm || { elements: [] });
    let arr;
    const today = $c.util.getComponent('dma_SubmitReq').get('today');
    let sdate = '';
    let edate = '';
    let disableYn = '';
    const check = $c.util.getComponent('slc_sltEduRnd1').getValue();
    let title = '';
    arr = slc_sltEduRnd1.value.split(",");
    title = $c.util.getComponent('slc_sltEduRnd1').getItemText($c.util.getComponent('slc_sltEduRnd1').getSelectedIndex());
    if (title === '2011년 상장법인 공시담당자 사이버교육') {
        await $c.win.alert("신청인원이 많아 9월15일부로 교육신청을 마감하겠습니다. 2012년에도 강의를 개설할 예정이니 많은 이용바랍니다");
        return;
    }
    if (arr !== "") {
        $c.util.getComponent('dma_SubmitReq').set('disclsEduApplSeq', arr[0]);
        sdate = arr[1];
        edate = arr[2];
        disableYn = arr[3];
        if (today > edate) {
            await $c.win.alert("제출 기간이 지났습니다.");
            return;
        }
        if (today < sdate) {
            await $c.win.alert("아직 제출 기간이 아닙니다.");
            return;
        }
        if (today >= sdate && today <= edate) {
            if ($c.util.getComponent('dma_SubmitReq').get('corpUserTpCd')=== '61') {
                form.action = 'eduRspn.do';
                $c.util.getComponent('dma_SubmitReq').set('method', 'educationResponsibilityForm');
                $c.util.getComponent('dma_SubmitReq').set('disableYn', disableYn);
                { const __nr = await scwin.tx_fn_Submit(); if (__nr && __nr.responseJSON && __nr.responseJSON.success === true) { $c.win.moveUrl("/jldfil16403/jldfil16403.xml", { "method": 'educationResponsibilityForm', "disableYn": disableYn }); } };
            } else {
                form.action = 'eduChrg.do';
                $c.util.getComponent('dma_SubmitReq').set('method', 'educationChargeForm');
                $c.util.getComponent('dma_SubmitReq').set('disableYn', disableYn);
                { const __nr = await scwin.tx_fn_Submit(); if (__nr && __nr.responseJSON && __nr.responseJSON.success === true) { $c.win.moveUrl("/jldfil16403/jldfil16403.xml", { "method": 'educationResponsibilityForm', "disableYn": disableYn }); } };
            }
        }
    } else {
        if (check === "") {
            await $c.win.alert("교육 회차를 선택해 주세요");
            return;
        }
    }
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.reset
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.reset = function () {
    /* sdd-asis-lifecycle:begin fn_Reset — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const form = (document.eduForm || { elements: [] });
    $c.util.getComponent('dma_SubmitReq').reset();
    const t_dsclEduRct = $c.util.getComponent("txt_dsclEduRct");
    t_dsclEduRct.innerHTML = "";
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.getDsclEduRct
 * @author Inswave
 * @date 2026. 09. 29
 * @param obj
 * @returns
 * @hidden N
*/
scwin.getDsclEduRct = function (obj) {
    /* sdd-asis-lifecycle:begin fn_GetDsclEduRct — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const slt_edu_rnd = obj.value;
    const t_dsclEduRct = $c.util.getComponent("txt_dsclEduRct");
    const arr = slt_edu_rnd.split(",");
    let sdate;
    let edate;
    if (arr !== "") {
        sdate = arr[1];
        edate = arr[2];
        t_dsclEduRct.innerHTML = "<b>제출 기간 : " + sdate + " ~ " + edate + "</b>";
    } else {
        t_dsclEduRct.innerHTML = "";
    }
    /* sdd-asis-lifecycle:end */
};
